public final class ChatListContainerNode: ASDisplayNode, ASGestureRecognizerDelegate {
    // GlowGram mod: custom background support.
    var exteraBackgroundNode: ASImageNode?
    var exteraBackgroundDimmingNode: ASDisplayNode?

    func exteraUpdateModBackground() {
        let store = ExteraPreferences.standard
        if let encoded = store.value(for: ExteraSettings.customChatListBackground),
           let data = Data(base64Encoded: encoded),
           let image = UIImage(data: data) {
            if self.exteraBackgroundNode == nil {
                self.exteraBackgroundNode = ASImageNode()
                self.exteraBackgroundNode?.contentMode = .scaleAspectFill
                self.exteraBackgroundNode?.isUserInteractionEnabled = false
                self.addSubnode(self.exteraBackgroundNode!)
            }
            self.exteraBackgroundNode?.image = image
            self.backgroundColor = .clear
            if self.exteraBackgroundDimmingNode == nil {
                self.exteraBackgroundDimmingNode = ASDisplayNode()
                self.exteraBackgroundDimmingNode?.backgroundColor = UIColor.black.withAlphaComponent(0.0)
                self.exteraBackgroundNode?.addSubnode(self.exteraBackgroundDimmingNode!)
            }
            let alpha = CGFloat(max(0.0, min(1.0, store.value(for: ExteraSettings.chatListBackgroundDimming))) * 0.85)
            self.exteraBackgroundDimmingNode?.backgroundColor = presentationData.theme.chatList.backgroundColor.withAlphaComponent(alpha)
        } else {
            self.exteraBackgroundNode?.image = nil
            self.exteraBackgroundNode?.removeFromSupernode()
            self.exteraBackgroundNode = nil
            self.exteraBackgroundDimmingNode = nil
            self.backgroundColor = presentationData.theme.chatList.backgroundColor
        }
    }
